import { setTimeout as sleep } from "node:timers/promises";

interface CircuitEntry {
  state: "closed" | "open" | "half-open";
  failures: number;
  openedAt: number;
}

interface HttpClient {
  post(url: string, payload: unknown): Promise<void>;
}

interface WebhookJob {
  host: string;
  endpoint: string;
  payload: unknown;
}

const FAILURE_THRESHOLD = 5;
const COOLDOWN_MS = 30_000;

/**
 * Delivers webhook jobs to destination endpoints, protecting each
 * destination host with an independent circuit breaker.
 */
export class WebhookDeliveryWorker {
  // Per-host circuit state, keyed by destination host.
  private circuits = new Map<string, CircuitEntry>();

  constructor(private readonly httpClient: HttpClient) {}

  /**
   * Returns whether a request to `host` is currently allowed through
   * the circuit breaker.
   */
  canSend(host: string): boolean {
    const entry = this.circuits.get(host);
    if (!entry || entry.state === "closed") {
      return true;
    }

    if (entry.state === "open") {
      const elapsed = Date.now() - entry.openedAt;
      if (elapsed < COOLDOWN_MS) {
        return false;
      }
      // Cool-down elapsed: allow a single probe through.
      entry.state = "half-open";
      return true;
    }

    // half-open: a probe is already in flight, but nothing here stops
    // a second caller from also treating this as the probe.
    return true;
  }

  /** Records a successful delivery to `host`, closing the circuit. */
  recordSuccess(host: string): void {
    this.circuits.set(host, {
      state: "closed",
      failures: 0,
      openedAt: 0,
    });
  }

  /** Records a failed delivery to `host`, tripping the breaker if needed. */
  recordFailure(host: string): void {
    const entry = this.circuits.get(host) ?? {
      state: "closed" as const,
      failures: 0,
      openedAt: 0,
    };

    entry.failures += 1;
    if (entry.failures >= FAILURE_THRESHOLD) {
      entry.state = "open";
      entry.openedAt = Date.now();
    }
    this.circuits.set(host, entry);
  }

  /** Main delivery loop: pulls jobs and sends them through the breaker. */
  async run(jobs: AsyncIterable<WebhookJob>): Promise<void> {
    for await (const job of jobs) {
      if (!this.canSend(job.host)) {
        continue;
      }

      try {
        await this.httpClient.post(job.endpoint, job.payload);
        this.recordSuccess(job.host);
      } catch {
        this.recordFailure(job.host);
        // Small backoff so a hot-looping failure doesn't spin the process.
        await sleep(50);
      }
    }
  }
}
